export class ApiError extends Error {
  /** HTTP status, or 0 when no response was received. */
  status: number
  /** Machine-readable code from the API's error body, or one generated by the client. */
  code: string
  details?: unknown

  constructor(status: number, code: string, message: string, details?: unknown) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.code = code
    this.details = details
  }
}

/** Client errors (4xx) won't succeed on retry; network and server errors might. */
export function isRetryable(error: unknown): boolean {
  return !(error instanceof ApiError && error.status >= 400 && error.status < 500 && error.status !== 429)
}

/** Copy for the API's stable error codes, so a wrong code reads differently from a dropped connection. */
const KNOWN_CODES: Record<string, string> = {
  otp_invalid: 'That code isn’t right. Please check the message we sent and try again.',
  account_not_found: 'We couldn’t find an account for that number. You can create one in a minute.',
  account_exists: 'There is already an account for that number. Try signing in instead.',
  locked_out: 'Too many attempts. For your security, please wait a few minutes and try again.',
  policy_not_found: 'We couldn’t match those details to a policy. Please check the policy number and ID number.',
}

/** Maps any thrown value to copy that is safe to show a family; never exposes server internals. */
export function getErrorMessage(error: unknown): string {
  if (error instanceof ApiError) {
    const specific = KNOWN_CODES[error.code]
    if (specific) return specific
    if (error.code === 'network_error' || error.code === 'timeout') {
      return 'We couldn’t reach the server. Please check your connection and try again.'
    }
    if (error.status === 422 || error.status === 400) return 'Please check the details you entered and try again.'
    if (error.status === 429) return 'Too many requests. Please wait a moment and try again.'
  }
  return 'Something went wrong on our side. Please try again shortly.'
}
